// Aim: every shape of if, as statement and as value, inline and block, with else if chains
// Note: The test file was partially generated by Claude Opus 5.5

import ifj26.*

// Prints the value followed by a new line
def printLine(value: String): Unit =
  print(value)
  print("\n")

def sign(x: Int): Int = if x < 0 then -1 else if x == 0 then 0 else 1

def describe(x: Int): Int =
  if x < 0 then return -1
  if x == 0 then return 0 else return 1

def absolute(x: Int): Int =
  return if x < 0 then 0 - x else x

def signBlock(x: Int): Int =
  return if x < 0 then -1
  else if x == 0 then 0 
  else 1

@main def ifForms(): Unit =
  val x = 5

  // Statement if
  if x > 0 then printLine(toStr(1))
  if x > 0 then printLine(toStr(2)) else printLine(toStr(3))
  if x > 0 then printLine(toStr(4))
  else printLine(toStr(5))

  if x > 0 then
    printLine(toStr(6))

  if x > 0 then
    printLine(toStr(7))
  else
    printLine(toStr(8))

  if x > 0 then printLine(toStr(9))
  else
    printLine(toStr(10))

  if x > 0 then
    printLine(toStr(11))
  else printLine(toStr(12))

  if x > 0 then printLine(toStr(13)); printLine(toStr(14))

  // else if chains
  if x < 0 then printLine(toStr(15)) else if x == 0 then printLine(toStr(16)) else printLine(toStr(17))

  if x < 0 then
    printLine(toStr(18))
  else if x == 0 then
    printLine(toStr(19))
  else if x == 1 then
    printLine(toStr(20))
  else
    printLine(toStr(21))

  // Nested if as the last thing in a block, several DEDENTs in a row
  if x > 0 then
    if x > 1 then
      if x > 2 then
        printLine(toStr(22))
  printLine(toStr(23))

  // Value if
  val v1 = if x < 0 then 0 - x else x
  val v2 = if x < 0 then -1 else if x == 0 then 0 else 1
  val v3 = if x < 0 then 1
  else 2

  val v4 = if x < 0 then
    1
  else
    2

  val v5 = if x < 0 then 1 else
    2

  var v6 = 0
  v6 = if x < 0 then 1 else 2
  v6 = if x < 0 then
    printLine(toStr(24))
    1
  else if x == 0 then
    printLine(toStr(25))
    2
  else
    printLine(toStr(26))
    3

  // Parentheses around a condition are just an expression
  if (x > 1) && (x < 10) then printLine(toStr(v1 + v2 + v3 + v4 + v5 + v6))
  printLine(toStr(sign(x) + describe(x) + absolute(x) + signBlock(x)))
